691	    _: ?*void,
692	    _: *xev.Loop,
693	    _: *xev.Completion,
694	    r: xev.Timer.CancelError!void,
695	) xev.CallbackAction {
696	    // This makes it easier to work across platforms where different platforms
697	    // support different sets of errors, so we just unify it.
698	    const CancelError = xev.Timer.CancelError || error{
699	        Canceled,
700	        NotFound,
701	        Unexpected,
702	    };
703	
704	    _ = r catch |err| switch (@as(CancelError, @errorCast(err))) {
705	        error.Canceled => {}, // success
706	        error.NotFound => {}, // completed before it could cancel
707	        else => {
708	            log.warn("error in cursor cancel callback err={}", .{err});
709	            unreachable;
710	        },
711	    };
712	
713	    return .disarm;
714	}
