    74	/// Initialize the grid.
    75	///
    76	/// The resolver must have a collection that supports deferred loading
    77	/// (collection.load_options != null). This is because we need the load
    78	/// options data to determine grid metrics and setup our sprite font.
    79	///
    80	/// SharedGrid always configures the sprite font. This struct is expected to be
    81	/// used with a terminal grid and therefore the sprite font is always
    82	/// necessary for correct rendering.
    83	pub fn init(
    84	    alloc: Allocator,
    85	    resolver: CodepointResolver,
    86	) InitError!SharedGrid {
    87	    const tw = init_tw;
    88	
    89	    // We need to support loading options since we use the size data
    90	    assert(resolver.collection.load_options != null);
    91	
    92	    var atlas_grayscale = try Atlas.init(alloc, 512, .grayscale);
    93	    errdefer atlas_grayscale.deinit(alloc);
    94	    var atlas_color = try Atlas.init(alloc, 512, .bgra);
    95	    errdefer atlas_color.deinit(alloc);
    96	
    97	    var result: SharedGrid = .{
    98	        .resolver = resolver,
    99	        .atlas_grayscale = atlas_grayscale,
   100	        .atlas_color = atlas_color,
   101	        .lock = .init,
   102	        .metrics = undefined, // Loaded below
   103	    };
   104	
   105	    // We set an initial capacity that can fit a good number of characters.
   106	    // This number was picked empirically based on my own terminal usage.
   107	    try tw.check(.codepoints_capacity);
   108	    try result.codepoints.ensureTotalCapacity(alloc, 128);
   109	    errdefer result.codepoints.deinit(alloc);
   110	    try tw.check(.glyphs_capacity);
   111	    try result.glyphs.ensureTotalCapacity(alloc, 128);
   112	    errdefer result.glyphs.deinit(alloc);
   113	
   114	    // Initialize our metrics.
   115	    try tw.check(.reload_metrics);
   116	    try result.reloadMetrics();
   117	
   118	    return result;
   119	}
