    91	        // The two extra lists hold cursor cells: index 0 is drawn before the
    92	        // row contents, and index row_count + 1 is drawn after them.
    93	        const fg_rows = try alloc.alloc(CellTextRow, row_count + 2);
    94	        @memset(fg_rows, .empty);
    95	        errdefer {
    96	            for (fg_rows) |*row| row.deinit(alloc);
